const body = msg.payload || {};
const now = new Date().toISOString();
const last = {
  type:'doorbell',
  endpoint:'legacy_phase9n',
  device_id: body.device_id || body.device || '#1',
  device_name: body.device_name || body.name || 'RT7 ESP32-S3-CAM',
  ip: body.ip || msg.req?.ip || '',
  source: body.source || 'esp32_button',
  count: body.count || 1,
  message: body.message || '有人按門鈴',
  time: now
};
flow.set('rt7_doorbell_last', last);
node.warn('[RT7_CLOUD_V3_REFERENCE][DOORBELL] '+JSON.stringify(last));
msg.payload = {ok:true, message:'doorbell received', state:{ok:true,last:last}};
return msg;

const e = Object.assign({time:new Date().toISOString(), server:'node_red_reference'}, msg.payload||{});
node.warn('[RT7_CLOUD_V3_REFERENCE][EVENT] '+JSON.stringify(e));
msg.payload={ok:true,event:e};
return msg;
